select
  "r1"."c0" as "customer_id",
  cast(
    cast(
      (
        select
          cast(
            (
              case
                when sign(n) * sign(d) < 0 then '-'
                else ''
              end
            ) || cast(q // 10000000000 as varchar) || '.' || lpad(cast(q % 10000000000 as varchar), 10, '0') as decimal(38, 10)
          )
        from
          (
            select
              n,
              d,
              case
                when n is null
                or d is null then null
                else (abs(n) * 10000000000) // abs(d) + case
                  when (abs(n) * 10000000000) % abs(d) >= abs(d) // 2 + abs(d) % 2 then 1
                  else 0
                end
              end as q
            from
              (
                select
                  cast(
                    replace(
                      cast(cast("r1"."c1" as decimal(38, 10)) as varchar),
                      '.',
                      ''
