                  ) as n,
                  nullif(
                    cast(
                      replace(
                        cast(cast("r1"."c2" as decimal(38, 10)) as varchar),
                        '.',
                        ''
                      ) as hugeint
                    ),
                    0
                  ) as d
              ) as golden_div_input
          ) as golden_div_rounded
      ) as decimal(38, 10)
    ) as decimal(38, 10)
  ) as "freight_ratio"
from
  (
    select
      "r3"."c0" as "c0",
      cast(
        sum(cast("r3"."c5" as decimal(38, 10))) as decimal(38, 10)
      ) as "c1",
      cast(
        sum(cast("r3"."c4" as decimal(38, 10))) as decimal(38, 10)
      ) as "c2"
    from
      (
        select
          "r4"."c0" as "c0",
          "r4"."c1" as "c1",
          "r4"."c2" as "c2",
          "r12"."c0" as "c3",
          "r12"."c1" as "c4",
          "r12"."c2" as "c5"
        from
          (
            select
              "customers"."customer_id" as "c0",
              "customers"."city" as "c1",
              "customers"."country" as "c2"
            from
              "customers"
          ) as "r4"
          left join (
            select
              "r6"."c2" as "c0",
              cast(
                coalesce("r6"."c7", cast($1 as integer)) as decimal(38, 10)
              ) as "c1",
              cast(
                coalesce("r6"."c5", cast($2 as integer)) as decimal(38, 10)
              ) as "c2"
            from
              (
                select
                  "r7"."c0" as "c0",
                  "r7"."c1" as "c1",
                  "r7"."c2" as "c2",
                  "r7"."c3" as "c3",
                  "r7"."c4" as "c4",
                  "r7"."c5" as "c5",
                  "r11"."c0" as "c6",
                  "r11"."c1" as "c7"
                from
                  (
                    select
                      "orders"."order_id" as "c0",
                      "orders"."order_date" as "c1",
                      "orders"."customer_id" as "c2",
                      "orders"."employee_id" as "c3",
                      "orders"."shipped_date" as "c4",
                      cast("orders"."freight" as decimal(38, 10)) as "c5"
                    from
                      "orders"
                  ) as "r7"
                  left join (
                    select
                      "order_details"."order_id" as "c0",
                      cast(
                        sum(
                          cast(
                            cast(
                              (
                                cast(
                                  cast(
                                    (
                                      cast(
                                        cast("order_details"."unit_price" as decimal(38, 10)) as decimal(38, 10)
                                      ) * cast("order_details"."quantity" as decimal(38, 10))
                                    ) as decimal(38, 10)
                                  ) as decimal(38, 10)
                                ) * cast(
                                  cast(
                                    (
                                      cast(cast($3 as integer) as decimal(38, 10)) - cast(
                                        cast("order_details"."discount" as decimal(38, 10)) as decimal(38, 10)
