                            ) as decimal(38, 10)
                          )
                        ) as decimal(38, 10)
                      ) as "c1"
                    from
                      "order_details"
                    group by
                      "order_details"."order_id"
                  ) as "r11" on ("r7"."c0" = "r11"."c0")
              ) as "r6"
          ) as "r12" on ("r4"."c0" = "r12"."c0")
      ) as "r3"
    group by
